const booking = $input.first().json;

// Sample items if not passed directly
const items = booking.itinerary_items || [
  {
    item_id: "ITM-2026-001-D1",
    supplier_id: "SUP-TRN-001",
    supplier_name: "Amalfi Luxury Chauffeurs",
    supplier_whatsapp: "+39333444555",
    supplier_email: "dispatch@amalfichauffeur.mock",
    service_title: "Private Mercedes V-Class Transfer: Naples Airport to Sorrento",
    service_date: booking.travel_start_date || "2026-09-20",
    service_time: "14:30",
    pax_count: booking.pax_adults || 2,
    client_name: booking.client_name || "Sarah Jenkins"
  },
  {
    item_id: "ITM-2026-001-D2",
    supplier_id: "SUP-GDE-001",
    supplier_name: "Capri & Pompeii Licensed Guides",
    supplier_whatsapp: "+39333666777",
    supplier_email: "info@pompeiiguides.mock",
    service_title: "Private VIP 3-Hour Guided Tour of Pompeii Ruins",
    service_date: "2026-09-21",
    service_time: "09:30",
    pax_count: booking.pax_adults || 2,
    client_name: booking.client_name || "Sarah Jenkins"
  }
];

const webhookBaseUrl = "https://your-n8n-instance.com/webhook/supplier-confirm";

const dispatchList = items.map(item => {
  const token = 'tok_' + Math.random().toString(36).substring(2, 15);
  return {
    json: {
      ...item,
      confirmation_token: token,
      accept_url: `${webhookBaseUrl}?token=${token}&action=accept&item_id=${item.item_id}`,
      decline_url: `${webhookBaseUrl}?token=${token}&action=decline&item_id=${item.item_id}`,
      message_text: `*NEW DMC BOOKING REQUEST*\n` +
        `Service: ${item.service_title}\n` +
        `Date & Time: ${item.service_date} @ ${item.service_time}\n` +
        `Guests: ${item.pax_count} Pax (Lead: ${item.client_name})\n\n` +
        `👉 *CONFIRM (1-Click):* ${webhookBaseUrl}?token=${token}&action=accept&item_id=${item.item_id}\n` +
        `❌ *DECLINE:* ${webhookBaseUrl}?token=${token}&action=decline&item_id=${item.item_id}`
    }
  };
});

return dispatchList;

const query = $input.first().json.query;
const action = query.action || 'accept';
const itemId = query.item_id || 'UNKNOWN';
const token = query.token;

const isConfirmed = action === 'accept';
const voucherNum = isConfirmed ? 'VOUCH-' + Math.floor(100000 + Math.random() * 900000) : null;

const htmlResponse = isConfirmed
  ? `<div style="font-family: sans-serif; text-align: center; padding: 50px;">
      <h1 style="color: #10B981;">✓ Service Confirmed!</h1>
      <p>Thank you. Your confirmation has been registered in the DMC Operations System.</p>
      <p><strong>Voucher Ref:</strong> ${voucherNum}</p>
     </div>`
  : `<div style="font-family: sans-serif; text-align: center; padding: 50px;">
      <h1 style="color: #EF4444;">✕ Service Declined</h1>
      <p>Operations has been alerted to reassign this booking to an alternate provider.</p>
     </div>`;

return [{
  json: {
    item_id: itemId,
    token: token,
    status: isConfirmed ? 'Confirmed' : 'Declined',
    voucher_number: voucherNum,
    html_response: htmlResponse
  }
}];
